class Solution {
    int length(RopeTreeNode* node) {
        if (!node) return 0;
        return node->left || node->right ? node->len : (int)node->val.size();
    }
public:
    char getKthCharacter(RopeTreeNode* root, int k) {
        RopeTreeNode* node = root;
        while (node->left || node->right) {
            int leftLen = length(node->left);
            if (k <= leftLen) node = node->left;
            else {
                k -= leftLen;
                node = node->right;
            }
        }
        return node->val[k - 1];
    }
};
